from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from django.db.models import Count
from .models import CSPPolicyGroup, CSPViolationRecord

class CSPPolicyBreakdownView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, policy_id):
        # Ensure policy belongs to the user's organization
        policy = CSPPolicyGroup.objects.filter(
            id=policy_id,
            organization=request.user.organization
        ).first()
        if not policy:
            return Response({"error": "Policy not found or access denied"}, status=status.HTTP_404_NOT_FOUND)

        breakdown = CSPViolationRecord.objects.filter(policy=policy).values(
            "violated_directive", "blocked_uri"
        ).annotate(incident_count=Count("id"))
        return Response({"policy": policy.name, "violations": list(breakdown)}, status=status.HTTP_200_OK)
